mapper.update:
UPDATE ai_user_resource_account SET
    total_balance = #{totalBalance},
    used_amount = #{usedAmount},
    frozen_amount = #{frozenAmount},
    unit = #{unit},
    last_tx_id = #{lastTxId},
    update_time = now()
WHERE user_id = #{userId}
  AND goods_type = #{goodsType}
  AND res_key = #{resKey}

